import json
import docx
import re

def process_text(text, data):
    # Handle relocation conditional
    if data.get('RELOCATION_PACKAGE') == 'Yes':
        text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
    else:
        text = re.sub(r'{{IF_RELOCATION}}.*?{{END_IF_RELOCATION}}', '', text, flags=re.DOTALL)

    # Handle other placeholders
    for key, value in data.items():
        placeholder = f"{{{{{key}}}}}"
        if placeholder in text:
            text = text.replace(placeholder, str(value))
    return text

def process_paragraphs(paragraphs, data):
    for para in paragraphs:
        # Check if any tag is present in the paragraph
        tags = ['{{IF_RELOCATION}}', '{{END_IF_RELOCATION}}'] + [f"{{{{{key}}}}}" for key in data]
        if any(tag in para.text for tag in tags):
            # Try run-level replacement first (preserves some formatting)
            for run in para.runs:
                for key, value in data.items():
                    placeholder = f"{{{{{key}}}}}"
                    if placeholder in run.text:
                        run.text = run.text.replace(placeholder, str(value))

                # Handle markers at run level too
                if data.get('RELOCATION_PACKAGE') == 'Yes':
                    run.text = run.text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
                # (Removing the whole block at run level is harder if it spans runs, 
                # so we'll rely on the paragraph-level check for the 'No' case)

            # Re-check and do paragraph-level replacement for anything missed (split across runs)
            if any(tag in para.text for tag in tags):
                para.text = process_text(para.text, data)

def process_tables(tables, data):
    for table in tables:
        for row in table.rows:
            for cell in row.cells:
                process_paragraphs(cell.paragraphs, data)
                if cell.tables:
                    process_tables(cell.tables, data)

# Load data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

# Load document
doc = docx.Document('offer_letter_template.docx')

# Process
process_paragraphs(doc.paragraphs, data)
process_tables(doc.tables, data)

# Save
doc.save('offer_letter_filled.docx')
print("Successfully generated offer_letter_filled.docx")
